overrides.style:
Menu, Dropdown, Popup, Dialog { border-radius: 18px; border: 1px solid var(--accent-soft); }
Sheet { border-radius: 24px 24px 0 0; border: 1px solid var(--accent-soft); }
SearchField#chats, SearchField#icons, TextField, Composer::field { border-radius: 16px; }
Fab { border-radius: 12px; }
IconTile[icon="theme"], IconTile[icon="storefront"] { border-radius: 12px; background: var(--accent-soft); color: var(--ink); }
